"""Finding the stretches of opening hours nobody covers."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.merging import merge_spans


def _clock(minute: int) -> str:
    return f"{minute // 60:02d}:{minute % 60:02d}"


def _label(begin: int, stop: int) -> str:
    clock = f"{_clock(begin)}-{_clock(stop)}"
    return f"gap {clock} ({stop - begin} min)"


def _check(spans: List[Span], opening: Span) -> None:
    for span in spans:
        if span.start < opening.start:
            raise ValueError(f"before opening: {span}")
        if span.end > opening.end:
            raise ValueError(f"after closing: {span}")


# ---
def find_gaps(
    worked: Iterable[Span], opening: Span
) -> List[str]:
    """Labels such as 'gap 12:00-13:00 (60 min)'."""
    spans = merge_spans(worked)
    _check(spans, opening)
    begin = [opening.start] + [item.end for item in spans]
    stop = [item.start for item in spans] + [opening.end]
    return [
        _label(left, right)
        for left, right in zip(begin, stop)
        if right > left
    ]

