import unittest

from hourglass.models import Span
from hourglass.gaps import find_gaps


class GapTests(unittest.TestCase):
    def test_middle_gap(self):
        spans = [Span(480, 720), Span(780, 1020)]
        self.assertEqual(
            find_gaps(spans, Span(480, 1020)),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_edges_and_empty(self):
        self.assertEqual(
            find_gaps([Span(540, 600)], Span(480, 660)),
            [
                "gap 08:00-09:00 (60 min)",
                "gap 10:00-11:00 (60 min)"
            ]
        )
        self.assertEqual(
            find_gaps([], Span(480, 540)),
            ["gap 08:00-09:00 (60 min)"]
        )

    def test_full_cover_has_no_gaps(self):
        spans = [Span(480, 600), Span(600, 660)]
        self.assertEqual(find_gaps(spans, Span(480, 660)), [])

    def test_outside_opening_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(420, 600)], Span(480, 660))
        with self.assertRaises(ValueError):
            find_gaps([Span(480, 700)], Span(480, 660))


if __name__ == "__main__":
    unittest.main()
